import { easeOutCubic, smootherstep } from "./motion.ts";

export type TopologyTransitionPhase =
  | "idle"
  | "exiting"
  | "handoff"
  | "entering"
  | "complete"
  | "cancelled";

export interface TopologyTransitionFrame {
  phase: TopologyTransitionPhase;
  progress: number;
  outgoingOpacity: number;
  incomingOpacity: number;
  hierarchyProgress: number;
  gridOpacity: number;
}

export interface TopologyTransitionFrameOptions {
  elapsed: number;
  duration?: number;
  reducedMotion?: boolean;
}

export interface TopologyTransitionLayer {
  element: HTMLElement | SVGElement;
}

export interface TopologyTransitionControllerOptions {
  duration?: number;
  reducedMotion?: boolean | (() => boolean);
  onFrame?: (frame: TopologyTransitionFrame) => void;
  onPhase?: (phase: TopologyTransitionPhase) => void;
}

export interface TopologyTransitionController {
  run(input: { outgoing: TopologyTransitionLayer; incoming: TopologyTransitionLayer }): Promise<void>;
  cancel(): void;
}

const defaultDuration = 1800;

function clamp01(value: number) {
  return Math.min(1, Math.max(0, value));
}

export function getTopologyTransitionFrame({
  elapsed,
  duration = defaultDuration,
  reducedMotion = false,
}: TopologyTransitionFrameOptions): TopologyTransitionFrame {
  if (reducedMotion) {
    return {
      phase: "complete",
      progress: 1,
      outgoingOpacity: 0,
      incomingOpacity: 1,
      hierarchyProgress: 1,
      gridOpacity: 1,
    };
  }

  const progress = clamp01(elapsed / Math.max(1, duration));
  const exitEnd = 0.34;
  const handoffEnd = 0.44;
  const outgoingOpacity = progress < exitEnd
    ? 1 - easeOutCubic(progress / exitEnd)
    : 0;
  const incomingOpacity = progress < handoffEnd
    ? 0
    : smootherstep(handoffEnd, 1, progress);
  const hierarchyProgress = progress < handoffEnd
    ? 0
    : smootherstep(handoffEnd, 1, progress);

  let phase: TopologyTransitionPhase = "entering";
  if (progress === 0) phase = "exiting";
  else if (progress < exitEnd) phase = "exiting";
  else if (progress < handoffEnd) phase = "handoff";
  else if (progress < 1) phase = "entering";
  else phase = "complete";

  return {
    phase,
    progress,
    outgoingOpacity,
    incomingOpacity,
    hierarchyProgress,
    gridOpacity: 1,
  };
}

export function getHierarchyRevealOpacity(
  depth: number,
  progress: number,
  depthCount = 3,
) {
  const normalizedDepth = Math.max(0, Math.min(depthCount - 1, depth));
  const depthSpan = 0.72 / Math.max(1, depthCount);
  const start = normalizedDepth * depthSpan;
  const end = Math.min(1, start + depthSpan * 1.7);

  return smootherstep(start, end, clamp01(progress));
}

function isReducedMotion(value: TopologyTransitionControllerOptions["reducedMotion"]) {
  return typeof value === "function" ? value() : Boolean(value);
}

function getOrderedRevealOpacity(order: number, progress: number, count: number) {
  const unit = 1 / Math.max(1, count);
  const start = order * unit * 0.78;
  const end = Math.min(1, start + unit * 1.35);
  return smootherstep(start, end, clamp01(progress));
}

function applyLayerFrame(
  layer: HTMLElement | SVGElement,
  opacity: number,
  hierarchyProgress: number,
  isIncoming: boolean,
) {
  layer.style.opacity = String(opacity);
  layer.style.pointerEvents = opacity > 0.02 ? "auto" : "none";
  layer.dataset.topologyTransitionVisibility = opacity > 0.02 ? "visible" : "hidden";

  if (!isIncoming) return;

  const elements = Array.from(layer.querySelectorAll<HTMLElement | SVGElement>("[data-topology-transition-kind]"));
  const orderedCount = elements.reduce((maximum, element) => {
    const order = Number(element.getAttribute("data-topology-transition-order"));
    return Number.isFinite(order) ? Math.max(maximum, order + 1) : maximum;
  }, 0);

  elements.forEach((element) => {
    const order = Number(element.getAttribute("data-topology-transition-order"));
    const depth = Number(element.getAttribute("data-topology-transition-depth") ?? 0);
    const elementOpacity = Number.isFinite(order)
      ? getOrderedRevealOpacity(order, hierarchyProgress, orderedCount)
      : getHierarchyRevealOpacity(depth, hierarchyProgress);
    if (element.style) {
      element.style.opacity = String(elementOpacity);
    }
  });
}

export function createTopologyTransitionController({
  duration = defaultDuration,
  reducedMotion = false,
  onFrame,
  onPhase,
}: TopologyTransitionControllerOptions = {}): TopologyTransitionController {
  let generation = 0;
  let frameHandle = 0;

  function cancel() {
    generation += 1;
    window.cancelAnimationFrame(frameHandle);
    onPhase?.("cancelled");
  }

  function run({ outgoing, incoming }: { outgoing: TopologyTransitionLayer; incoming: TopologyTransitionLayer }) {
    cancel();
    const currentGeneration = generation;
    const shouldReduce = isReducedMotion(reducedMotion);
    const startedAt = performance.now();

    return new Promise<void>((resolve) => {
      const render = (now: number) => {
        if (currentGeneration !== generation) {
          resolve();
          return;
        }

        const frame = getTopologyTransitionFrame({
          elapsed: now - startedAt,
          duration,
          reducedMotion: shouldReduce,
        });
        onPhase?.(frame.phase);
        applyLayerFrame(outgoing.element, frame.outgoingOpacity, 0, false);
        applyLayerFrame(incoming.element, frame.incomingOpacity, frame.hierarchyProgress, true);
        onFrame?.(frame);

        if (frame.phase === "complete") {
          applyLayerFrame(outgoing.element, 0, 0, false);
          applyLayerFrame(incoming.element, 1, 1, true);
          resolve();
          return;
        }

        frameHandle = window.requestAnimationFrame(render);
      };

      frameHandle = window.requestAnimationFrame(render);
    });
  }

  return { run, cancel };
}
